import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        Solver solver = new Solver();
        solver.solve(in, out);
        out.close();
    }

    static class Solver {
        int n, m;

        void solve(InputReader in, OutputWriter out) {
            n = in.nextInt();
            m = in.nextInt();
            long answer = 0;

            if (n > 100) {
                int rem = (n - 100) % 6;
                long q = (n - 100) / 6;
                answer += q * 6L * m;
                n = 100 + rem;
            }

            if (m > 100) {
                int rem = (m - 100) % 6;
                long q = (m - 100) / 6;
                answer += q * 6L * n;
                m = 100 + rem;
            }

            int[][] id = new int[n + 1][m + 1];
            int even = 1;
            int odd = 1;

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (((i + j) & 1) == 0) id[i][j] = even++;
                }
            }
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (((i + j) & 1) != 0) id[i][j] = odd++;
                }
            }

            int oddCount = odd - 1;
            int evenCount = even - 1;

            List<Integer>[] graph = new List[oddCount + 1];
            for (int i = 0; i <= oddCount; i++) graph[i] = new ArrayList<>();

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (((i + j) & 1) != 0) {
                        addEdge(graph, id, i, j, i - 3, j);
                        addEdge(graph, id, i, j, i - 2, j - 1);
                        addEdge(graph, id, i, j, i - 2, j + 1);
                        addEdge(graph, id, i, j, i, j - 3);
                        addEdge(graph, id, i, j, i - 1, j - 2);
                        addEdge(graph, id, i, j, i + 1, j - 2);
                        addEdge(graph, id, i, j, i, j + 3);
                        addEdge(graph, id, i, j, i - 1, j + 2);
                        addEdge(graph, id, i, j, i + 1, j + 2);
                        addEdge(graph, id, i, j, i + 3, j);
                        addEdge(graph, id, i, j, i + 2, j - 1);
                        addEdge(graph, id, i, j, i + 2, j + 1);
                    }
                }
            }

            HopcroftKarp hk = new HopcroftKarp(oddCount, evenCount, graph);
            answer += 2L * hk.maxMatching();
            out.println(answer);
        }

        void addEdge(List<Integer>[] graph, int[][] id, int i, int j, int s, int t) {
            if (s <= 0 || t <= 0 || s > n || t > m) return;
            graph[id[i][j]].add(id[s][t]);
        }
    }

    static class HopcroftKarp {
        static final int INF = 10000000;
        static final int NIL = 0;

        int m, n;
        List<Integer>[] graph;
        int[] pairU, pairV, dist;

        HopcroftKarp(int m, int n, List<Integer>[] graph) {
            this.m = m;
            this.n = n;
            this.graph = graph;
            pairU = new int[m + 1];
            pairV = new int[n + 1];
            dist = new int[m + 1];
        }

        int maxMatching() {
            Arrays.fill(pairU, NIL);
            Arrays.fill(pairV, NIL);
            int res = 0;
            while (bfs()) {
                for (int i = 1; i <= m; i++) {
                    if (pairU[i] == NIL && dfs(i)) res++;
                }
            }
            return res;
        }

        boolean bfs() {
            ArrayDeque<Integer> queue = new ArrayDeque<>();
            for (int i = 1; i <= m; i++) {
                if (pairU[i] == NIL) {
                    queue.add(i);
                    dist[i] = 0;
                } else {
                    dist[i] = INF;
                }
            }
            dist[NIL] = INF;
            while (!queue.isEmpty()) {
                int u = queue.poll();
                if (dist[u] < dist[NIL]) {
                    for (int v : graph[u]) {
                        if (dist[pairV[v]] == INF) {
                            queue.add(pairV[v]);
                            dist[pairV[v]] = dist[u] + 2;
                        }
                    }
                }
            }
            return dist[NIL] < INF;
        }

        boolean dfs(int u) {
            if (u == NIL) return true;
            for (int v : graph[u]) {
                if (dist[pairV[v]] == dist[u] + 2) {
                    if (dfs(pairV[v])) {
                        pairV[v] = u;
                        pairU[u] = v;
                        return true;
                    }
                }
            }
            dist[u] = INF;
            return false;
        }
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) return filter.isSpaceChar(c);
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void println(long i) {
            writer.println(i);
        }
    }
}
